    function automatic [7:0] xtime(input [7:0] a);
        xtime = {a[6:0], 1'b0} ^ (8'h1b & {8{a[7]}});
    endfunction

    function automatic [31:0] mix_col(input [31:0] c);
        reg [7:0] s0, s1, s2, s3;
        begin
            {s0, s1, s2, s3} = c;
            mix_col = {
                xtime(s0) ^ (xtime(s1) ^ s1) ^ s2 ^ s3,
                s0 ^ xtime(s1) ^ (xtime(s2) ^ s2) ^ s3,
                s0 ^ s1 ^ xtime(s2) ^ (xtime(s3) ^ s3),
                (xtime(s0) ^ s0) ^ s1 ^ s2 ^ xtime(s3)
            };
        end
    endfunction

    function automatic [127:0] sub_bytes(input [127:0] s);
        integer i;
        begin
            for (i = 0; i < 16; i = i + 1)
                sub_bytes[127 - 8*i -: 8] = aes_sbox(s[127 - 8*i -: 8]);
        end
    endfunction

    function automatic [127:0] shift_rows(input [127:0] s);
        reg [7:0] b [0:15];
        integer i;
        begin
            for (i = 0; i < 16; i = i + 1)
                b[i] = s[127 - 8*i -: 8];
            shift_rows = {
                b[0], b[5], b[10], b[15],
                b[4], b[9], b[14], b[3],
                b[8], b[13], b[2], b[7],
                b[12], b[1], b[6], b[11]
            };
        end
    endfunction

    function automatic [127:0] mix_columns(input [127:0] s);
        begin
            mix_columns = {
                mix_col(s[127:96]),
                mix_col(s[95:64]),
                mix_col(s[63:32]),
                mix_col(s[31:0])
            };
        end
    endfunction

    function automatic [31:0] rcon(input integer round);
        begin
            case (round)
                1: rcon = 32'h01000000;
                2: rcon = 32'h02000000;
                3: rcon = 32'h04000000;
                4: rcon = 32'h08000000;
                5: rcon = 32'h10000000;
                6: rcon = 32'h20000000;
                7: rcon = 32'h40000000;
                8: rcon = 32'h80000000;
                9: rcon = 32'h1b000000;
                10: rcon = 32'h36000000;
                default: rcon = 32'h00000000;
            endcase
        end
