    function automatic [127:0] aes_encrypt(input [127:0] pt, input [127:0] k);
        reg [31:0] w [0:43];
        reg [127:0] state;
        integer i;
        begin
            w[0] = k[127:96];
            w[1] = k[95:64];
            w[2] = k[63:32];
            w[3] = k[31:0];
            for (i = 4; i < 44; i = i + 1) begin
                if ((i % 4) == 0)
