        end
    endfunction

    function automatic [127:0] shift_rows(input [127:0] s);
        reg [7:0] b [0:15];
        integer i;
        begin
            for (i = 0; i < 16; i = i + 1)
                b[i] = s[127 - 8*i -: 8];
            shift_rows = {
                b[0], b[5], b[10], b[15],
                b[4], b[9], b[14], b[3],
                b[8], b[13], b[2], b[7],
                b[12], b[1], b[6], b[11]
