                mix_col(s[95:64]),
                mix_col(s[63:32]),
                mix_col(s[31:0])
            };
        end
    endfunction

    function automatic [31:0] rcon(input integer round);
        begin
            case (round)
                1: rcon = 32'h01000000;
                2: rcon = 32'h02000000;
                3: rcon = 32'h04000000;
                4: rcon = 32'h08000000;
                5: rcon = 32'h10000000;
                6: rcon = 32'h20000000;
                7: rcon = 32'h40000000;
                8: rcon = 32'h80000000;
                9: rcon = 32'h1b000000;
