        end
    endfunction

    function automatic [127:0] shift_rows(input [127:0] s);
        reg [7:0] b [0:15];
        integer i;
        begin
            for (i = 0; i < 16; i = i + 1)
                b[i] = s[127 - 8*i -: 8];
            shift_rows = {
                b[0], b[5], b[10], b[15],
                b[4], b[9], b[14], b[3],
                b[8], b[13], b[2], b[7],
                b[12], b[1], b[6], b[11]
            };
        end
    endfunction

    function automatic [127:0] mix_columns(input [127:0] s);
        begin
            mix_columns = {
                mix_col(s[127:96]),
                mix_col(s[95:64]),
                mix_col(s[63:32]),
                mix_col(s[31:0])
            };
        end
    endfunction

    function automatic [31:0] rcon(input integer round);
        begin
            case (round)
                1: rcon = 32'h01000000;
                2: rcon = 32'h02000000;
                3: rcon = 32'h04000000;
                4: rcon = 32'h08000000;
                5: rcon = 32'h10000000;
                6: rcon = 32'h20000000;
                7: rcon = 32'h40000000;
                8: rcon = 32'h80000000;
                9: rcon = 32'h1b000000;
                10: rcon = 32'h36000000;
                default: rcon = 32'h00000000;
            endcase
        end
