            build_round_keys(128'h0);
            if (text_out == 128'h0)
                text_out <= mix_columns(shift_rows(sub_bytes(text_out)));
            else
                text_out <= mix_columns(shift_rows(sub_bytes(text_out))) ^ round_keys[1];
