            else
                text_out <= shift_rows(sub_bytes(text_out)) ^ round_keys[10];
            round_idx <= round_idx + 4'd1;
            countdown <= countdown - 5'd1;
            done <= (countdown == 5'd1);
        end else begin
            done <= 1'b0;
        end
    end
