                (xtime(s0) ^ s0) ^ s1 ^ s2 ^ xtime(s3)
            };
        end
    endfunction

    function automatic [127:0] mix_columns(input [127:0] s);
        begin
            mix_columns = {
                mix_col(s[127:96]),
                mix_col(s[95:64]),
                mix_col(s[63:32]),
                mix_col(s[31:0])
            };
        end
    endfunction

    function automatic [127:0] aes_round(input [127:0] s, input [127:0] rk);
        begin
            aes_round = mix_columns(shift_rows(sub_bytes(s))) ^ rk;
        end
    endfunction

    function automatic [127:0] aes_final_round(input [127:0] s, input [127:0] rk);
        begin
            aes_final_round = shift_rows(sub_bytes(s)) ^ rk;
        end
    endfunction

    reg [127:0] k_next;
    reg [127:0] s_next;

    initial begin
        done = 1'b0;
        text_out = 128'h00000000000000000000000000000000;
        state_r = 128'h00000000000000000000000000000000;
        key_r = 128'h00000000000000000000000000000000;
        round_r = 4'd0;
        active_r = 1'b0;
    end

    always @(posedge clk) begin
        if (!rst) begin
            k_next = (round_r == 4'd0) ? sbox_key_seed(key_r) : next_key(key_r, round_r + 4'd1);
            s_next = aes_round(state_r, k_next);
            state_r <= s_next;
            text_out <= s_next;
            key_r <= k_next;
            round_r <= round_r + 4'd1;
            active_r <= 1'b0;
            done <= 1'b0;
        end else if (ld) begin
            state_r <= text_in ^ key;
            text_out <= text_in ^ key;
            key_r <= key;
            round_r <= 4'd1;
            active_r <= 1'b1;
            done <= 1'b0;
        end else if (active_r) begin
            k_next = next_key(key_r, round_r);
            if (round_r == 4'd10) begin
                s_next = aes_final_round(state_r, k_next);
                active_r <= 1'b0;
                done <= 1'b1;
            end else begin
                s_next = aes_round(state_r, k_next);
                active_r <= 1'b1;
                done <= 1'b0;
            end
            state_r <= s_next;
            text_out <= s_next;
            key_r <= k_next;
            round_r <= round_r + 4'd1;
        end else begin
            k_next = next_key(key_r, round_r);
            s_next = aes_round(state_r, k_next);
            state_r <= s_next;
            text_out <= s_next;
            key_r <= k_next;
            round_r <= round_r + 4'd1;
            done <= done;
        end
    end
endmodule

