module aes_cipher_top(
    input clk,
    input rst,
    input ld,
    output done,
    input [127:0] key,
    input [127:0] text_in,
    output [127:0] text_out
);
    reg [127:0] state_reg;
    reg [127:0] key_reg;
    reg [3:0] round_reg;
    reg busy_reg;
    reg done_reg;
    reg [127:0] text_out_reg;

    wire [127:0] round_key_next;
    wire [127:0] state_next_full;
    wire [127:0] state_next_last;

    assign done = done_reg;
    assign text_out = text_out_reg;

    aes_key_step u_key_step (
        .round(round_reg + 4'd1),
        .key_in(key_reg),
        .key_out(round_key_next)
    );

    aes_state_step u_state_step_full (
        .state_in(state_reg),
        .round_key(round_key_next),
        .last_round(1'b0),
        .state_out(state_next_full)
    );

    aes_state_step u_state_step_last (
        .state_in(state_reg),
        .round_key(round_key_next),
        .last_round(1'b1),
        .state_out(state_next_last)
    );

    always @(posedge clk) begin
        if (!rst) begin
            state_reg <= 128'h0;
            key_reg <= 128'h0;
            round_reg <= 4'd0;
            busy_reg <= 1'b0;
            done_reg <= 1'b0;
            text_out_reg <= 128'h0;
        end else if (ld) begin
            state_reg <= text_in ^ key;
            key_reg <= key;
            round_reg <= 4'd0;
            busy_reg <= 1'b1;
            done_reg <= 1'b0;
            text_out_reg <= text_in ^ key;
        end else if (busy_reg) begin
            if (round_reg < 4'd9) begin
                state_reg <= state_next_full;
                key_reg <= round_key_next;
                round_reg <= round_reg + 4'd1;
                done_reg <= 1'b0;
                text_out_reg <= state_next_full;
            end else begin
                state_reg <= state_next_last;
                key_reg <= round_key_next;
                round_reg <= 4'd10;
                busy_reg <= 1'b0;
                done_reg <= 1'b1;
                text_out_reg <= state_next_last;
            end
        end else begin
            done_reg <= 1'b0;
        end
    end
endmodule

module aes_state_step(
    input [127:0] state_in,
    input [127:0] round_key,
    input last_round,
    output [127:0] state_out
);
    wire [127:0] sb;
    wire [127:0] sr;
    wire [127:0] mc;

    aes_sub_bytes u_sub_bytes(.s_in(state_in), .s_out(sb));
    aes_shift_rows u_shift_rows(.s_in(sb), .s_out(sr));
    aes_mix_columns u_mix_columns(.s_in(sr), .s_out(mc));

    assign state_out = (last_round ? sr : mc) ^ round_key;
endmodule

module aes_key_step(
    input [3:0] round,
    input [127:0] key_in,
    output [127:0] key_out
);
    wire [31:0] w0 = key_in[127:96];
    wire [31:0] w1 = key_in[95:64];
    wire [31:0] w2 = key_in[63:32];
    wire [31:0] w3 = key_in[31:0];

    wire [31:0] t = aes_sub_word({w3[23:0], w3[31:24]}) ^ aes_rcon(round);
    wire [31:0] nw0 = w0 ^ t;
    wire [31:0] nw1 = w1 ^ nw0;
    wire [31:0] nw2 = w2 ^ nw1;
    wire [31:0] nw3 = w3 ^ nw2;

    assign key_out = {nw0, nw1, nw2, nw3};

    function automatic [31:0] aes_sub_word(input [31:0] w);
        begin
            aes_sub_word = {
                aes_sbox_fn(w[31:24]),
                aes_sbox_fn(w[23:16]),
                aes_sbox_fn(w[15:8]),
                aes_sbox_fn(w[7:0])
            };
        end
    endfunction

    function automatic [31:0] aes_rcon(input [3:0] r);
        begin
            case (r)
                4'd1: aes_rcon = 32'h01000000;
                4'd2: aes_rcon = 32'h02000000;
                4'd3: aes_rcon = 32'h04000000;
                4'd4: aes_rcon = 32'h08000000;
                4'd5: aes_rcon = 32'h10000000;
                4'd6: aes_rcon = 32'h20000000;
                4'd7: aes_rcon = 32'h40000000;
                4'd8: aes_rcon = 32'h80000000;
                4'd9: aes_rcon = 32'h1b000000;
                4'd10: aes_rcon = 32'h36000000;
                default: aes_rcon = 32'h00000000;
            endcase
        end
    endfunction
endmodule

module aes_sub_bytes(
    input [127:0] s_in,
    output [127:0] s_out
);
    genvar i;
    generate
        for (i = 0; i < 16; i = i + 1) begin : g_sbox
            assign s_out[127 - 8*i -: 8] = aes_sbox_fn(s_in[127 - 8*i -: 8]);
        end
    endgenerate
endmodule

