module aes_mix_columns(
    input [127:0] s_in,
    output [127:0] s_out
);
    assign s_out[127:96] = aes_mix_col_fn(s_in[127:96]);
    assign s_out[95:64]  = aes_mix_col_fn(s_in[95:64]);
    assign s_out[63:32]  = aes_mix_col_fn(s_in[63:32]);
    assign s_out[31:0]   = aes_mix_col_fn(s_in[31:0]);

    function automatic [31:0] aes_mix_col_fn(input [31:0] c);
        reg [7:0] s0;
        reg [7:0] s1;
        reg [7:0] s2;
        reg [7:0] s3;
        begin
            s0 = c[31:24];
            s1 = c[23:16];
            s2 = c[15:8];
            s3 = c[7:0];
            aes_mix_col_fn = {
                aes_xtime_fn(s0) ^ (aes_xtime_fn(s1) ^ s1) ^ s2 ^ s3,
                s0 ^ aes_xtime_fn(s1) ^ (aes_xtime_fn(s2) ^ s2) ^ s3,
                s0 ^ s1 ^ aes_xtime_fn(s2) ^ (aes_xtime_fn(s3) ^ s3),
                (aes_xtime_fn(s0) ^ s0) ^ s1 ^ s2 ^ aes_xtime_fn(s3)
            };
        end
    endfunction

    function automatic [7:0] aes_xtime_fn(input [7:0] a);
        begin
            aes_xtime_fn = {a[6:0], 1'b0} ^ (8'h1b & {8{a[7]}});
        end
    endfunction
endmodule

