module aes_cipher_top(
    input clk,
    input rst,
    input ld,
    output done,
    input [127:0] key,
    input [127:0] text_in,
    output [127:0] text_out
);
    reg [127:0] state;
    reg [127:0] round_key;
    reg [3:0] round;
    reg busy;
    reg done_r;

    wire [127:0] next_round_key;
    wire [127:0] round_state;
    wire [127:0] final_state;

    assign done = done_r;
    assign text_out = state;

    aes_key_step u_key_step(
        .round(round),
        .key_in(round_key),
        .key_out(next_round_key)
    );

    aes_state_step u_state_step(
        .state_in(state),
        .round_key(next_round_key),
        .final_round(1'b0),
        .state_out(round_state)
    );

    aes_state_step u_final_step(
        .state_in(state),
        .round_key(next_round_key),
        .final_round(1'b1),
        .state_out(final_state)
    );

    always @(posedge clk) begin
        if (!rst) begin
            state <= 128'h0;
            round_key <= 128'h0;
            round <= 4'd0;
            busy <= 1'b0;
            done_r <= 1'b0;
        end else if (ld) begin
            state <= text_in ^ key;
            round_key <= key;
            round <= 4'd1;
            busy <= 1'b1;
            done_r <= 1'b0;
        end else if (busy) begin
            round_key <= next_round_key;
            if (round < 4'd10) begin
                state <= round_state;
                round <= round + 4'd1;
                done_r <= 1'b0;
            end else begin
                state <= final_state;
                round <= 4'd0;
                busy <= 1'b0;
                done_r <= 1'b1;
            end
        end else begin
            done_r <= 1'b0;
        end
    end
endmodule

module aes_key_step(
    input [3:0] round,
    input [127:0] key_in,
    output [127:0] key_out
);
    wire [31:0] w0 = key_in[127:96];
    wire [31:0] w1 = key_in[95:64];
    wire [31:0] w2 = key_in[63:32];
    wire [31:0] w3 = key_in[31:0];

    wire [31:0] t = sub_word({w3[23:0], w3[31:24]}) ^ rcon(round);
    wire [31:0] nw0 = w0 ^ t;
    wire [31:0] nw1 = w1 ^ nw0;
    wire [31:0] nw2 = w2 ^ nw1;
    wire [31:0] nw3 = w3 ^ nw2;

    assign key_out = {nw0, nw1, nw2, nw3};

    function automatic [31:0] rcon(input [3:0] r);
        begin
            case (r)
                4'd1: rcon = 32'h01000000;
                4'd2: rcon = 32'h02000000;
                4'd3: rcon = 32'h04000000;
                4'd4: rcon = 32'h08000000;
                4'd5: rcon = 32'h10000000;
                4'd6: rcon = 32'h20000000;
                4'd7: rcon = 32'h40000000;
                4'd8: rcon = 32'h80000000;
                4'd9: rcon = 32'h1b000000;
                4'd10: rcon = 32'h36000000;
