module aes_cipher_top(
    input clk,
    input rst,
    input ld,
    output done,
    input [127:0] key,
    input [127:0] text_in,
    output [127:0] text_out
);
    reg [127:0] state;
    reg [127:0] round_key;
    reg [3:0] round;
    wire [127:0] next_state;
    wire [127:0] next_key;
    wire final_round;

    assign final_round = (round == 4'd10);
    assign text_out = state;

    aes_state_step u_state_step(
        .state(state),
        .round_key(next_key),
        .final_round(final_round),
        .next_state(next_state)
    );

    aes_key_step u_key_step(
        .key_in(round_key),
        .round(round),
        .key_out(next_key)
    );

    aes_done_ctrl u_done_ctrl(
        .clk(clk),
        .rst(rst),
        .ld(ld),
        .done(done)
    );

    always @(posedge clk) begin
        if (!rst) begin
            state <= 128'h0;
            round_key <= 128'h0;
            round <= 4'd0;
        end else if (ld) begin
            state <= text_in ^ key;
            round_key <= key;
            round <= 4'd1;
        end else if (round != 4'd0) begin
            state <= next_state;
            round_key <= next_key;
            if (round == 4'd10)
                round <= 4'd0;
            else
                round <= round + 4'd1;
        end
    end
endmodule

module aes_done_ctrl(
    input clk,
    input rst,
    input ld,
    output reg done
);
    reg [3:0] dcnt;

    always @(posedge clk) begin
        if (!rst)
            dcnt <= 4'd0;
        else if (ld)
            dcnt <= 4'd11;
        else if (|dcnt)
            dcnt <= dcnt - 4'd1;
    end

    always @(posedge clk) begin
        if (!rst)
            done <= 1'b0;
        else
            done <= (dcnt == 4'd1) && !ld;
    end
endmodule

