module aes_state_step(
    input [127:0] state,
    input [127:0] round_key,
    input final_round,
    output [127:0] next_state
);
    wire [127:0] sb;
    wire [127:0] sr;
    wire [127:0] mc;

    assign sb = aes_sub_bytes(state);
    assign sr = aes_shift_rows(sb);
    assign mc = aes_mix_columns(sr);
    assign next_state = (final_round ? sr : mc) ^ round_key;

    function automatic [127:0] aes_sub_bytes(input [127:0] s);
        integer i;
        begin
            for (i = 0; i < 16; i = i + 1)
                aes_sub_bytes[127 - 8*i -: 8] = aes_sbox(s[127 - 8*i -: 8]);
        end
    endfunction

    function automatic [127:0] aes_shift_rows(input [127:0] s);
        reg [7:0] b [0:15];
        integer i;
        begin
            for (i = 0; i < 16; i = i + 1)
                b[i] = s[127 - 8*i -: 8];
            aes_shift_rows = {
                b[0], b[5], b[10], b[15],
                b[4], b[9], b[14], b[3],
                b[8], b[13], b[2], b[7],
                b[12], b[1], b[6], b[11]
            };
        end
    endfunction

    function automatic [127:0] aes_mix_columns(input [127:0] s);
        begin
            aes_mix_columns = {
                aes_mix_col(s[127:96]),
                aes_mix_col(s[95:64]),
                aes_mix_col(s[63:32]),
                aes_mix_col(s[31:0])
            };
        end
    endfunction

    function automatic [31:0] aes_mix_col(input [31:0] c);
        reg [7:0] s0, s1, s2, s3;
        begin
            {s0, s1, s2, s3} = c;
            aes_mix_col = {
                aes_xtime(s0) ^ (aes_xtime(s1) ^ s1) ^ s2 ^ s3,
                s0 ^ aes_xtime(s1) ^ (aes_xtime(s2) ^ s2) ^ s3,
                s0 ^ s1 ^ aes_xtime(s2) ^ (aes_xtime(s3) ^ s3),
                (aes_xtime(s0) ^ s0) ^ s1 ^ s2 ^ aes_xtime(s3)
            };
        end
    endfunction

