    endfunction

    function automatic [7:0] xtime(input [7:0] a);
        begin
            xtime = {a[6:0], 1'b0} ^ ({8{a[7]}} & 8'h1b);
        end
    endfunction

    function automatic [31:0] mix_word(input [31:0] w);
        reg [7:0] a0;
        reg [7:0] a1;
        reg [7:0] a2;
        reg [7:0] a3;
        begin
            a0 = w[31:24];
            a1 = w[23:16];
            a2 = w[15:8];
            a3 = w[7:0];
            mix_word = {
                xtime(a0) ^ xtime(a1) ^ a1 ^ a2 ^ a3,
                a0 ^ xtime(a1) ^ xtime(a2) ^ a2 ^ a3,
                a0 ^ a1 ^ xtime(a2) ^ xtime(a3) ^ a3,
                xtime(a0) ^ a0 ^ a1 ^ a2 ^ xtime(a3)
            };
        end
    endfunction

    function automatic [127:0] sub_bytes(input [127:0] x);
        integer i;
        begin
            for (i = 0; i < 16; i = i + 1)
                sub_bytes[127 - (i * 8) -: 8] = sbox(x[127 - (i * 8) -: 8]);
        end
    endfunction

    function automatic [127:0] shift_rows(input [127:0] x);
        reg [7:0] b0;  reg [7:0] b1;  reg [7:0] b2;  reg [7:0] b3;
