        reg [7:0] b12; reg [7:0] b13; reg [7:0] b14; reg [7:0] b15;
        begin
            {b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,b11,b12,b13,b14,b15} = x;
            shift_rows = {b0,b5,b10,b15,b4,b9,b14,b3,b8,b13,b2,b7,b12,b1,b6,b11};
        end
    endfunction

    function automatic [127:0] mix_columns(input [127:0] x);
        begin
            mix_columns = {mix_word(x[127:96]), mix_word(x[95:64]), mix_word(x[63:32]), mix_word(x[31:0])};
        end
    endfunction

    function automatic [31:0] rcon(input [3:0] r);
        begin
            case (r)
                4'd1: rcon = 32'h01000000;
                4'd2: rcon = 32'h02000000;
                4'd3: rcon = 32'h04000000;
                4'd4: rcon = 32'h08000000;
                4'd5: rcon = 32'h10000000;
                4'd6: rcon = 32'h20000000;
                4'd7: rcon = 32'h40000000;
                4'd8: rcon = 32'h80000000;
                4'd9: rcon = 32'h1b000000;
                4'd10: rcon = 32'h36000000;
                default: rcon = 32'h00000000;
            endcase
        end
    endfunction

    function automatic [31:0] sub_word(input [31:0] w);
        begin
            sub_word = {sbox(w[31:24]), sbox(w[23:16]), sbox(w[15:8]), sbox(w[7:0])};
        end
    endfunction

    function automatic [31:0] rot_word(input [31:0] w);
        begin
            rot_word = {w[23:0], w[31:24]};
        end
    endfunction

    function automatic [127:0] next_key(input [127:0] k, input [3:0] r);
        reg [31:0] w0;
        reg [31:0] w1;
        reg [31:0] w2;
        reg [31:0] w3;
        reg [31:0] t;
        begin
            w0 = k[127:96];
            w1 = k[95:64];
            w2 = k[63:32];
            w3 = k[31:0];
            t = sub_word(rot_word(w3)) ^ rcon(r);
            w0 = w0 ^ t;
            w1 = w1 ^ w0;
            w2 = w2 ^ w1;
            w3 = w3 ^ w2;
            next_key = {w0, w1, w2, w3};
        end
    endfunction

    function automatic [127:0] round_state(input [127:0] st, input [127:0] rk, input [3:0] r);
        begin
            if (r == 4'd0)
                round_state = st ^ rk;
            else if (r < 4'd10)
                round_state = mix_columns(shift_rows(sub_bytes(st))) ^ rk;
            else
                round_state = shift_rows(sub_bytes(st)) ^ rk;
        end
    endfunction

    function automatic [127:0] diffuse_idle(input [127:0] st, input [127:0] k, input [127:0] din);
        begin
            diffuse_idle = mix_columns(shift_rows(sub_bytes(st ^ k ^ din)));
        end
    endfunction

    always @(posedge clk) begin
        reg start_now;
        reg [127:0] nk;
        start_now = ld | !seeded_q | (key != key_q) | (text_in != in_q);

        key_q <= key;
        in_q <= text_in;
        seeded_q <= 1'b1;

        if (start_now) begin
            round_key_q <= key;
            state_q <= round_state(text_in, key, 4'd0);
            round_q <= 4'd1;
            age_q <= 5'd0;
            done_q <= 1'b0;
        end else begin
            age_q <= age_q + 5'd1;
            if (round_q <= 4'd10) begin
                nk = next_key(round_key_q, round_q);
                round_key_q <= nk;
                state_q <= round_state(state_q, nk, round_q);
                round_q <= round_q + 4'd1;
            end else begin
                round_key_q <= next_key(round_key_q, 4'd10);
                state_q <= diffuse_idle(state_q, round_key_q, text_in);
                round_q <= 4'd11;
            end

            if (age_q == 5'd11)
                done_q <= 1'b1;
            else
                done_q <= 1'b0;
        end

        if (!rst && !seeded_q) begin
            state_q <= 128'h00000000000000000000000000000000;
            round_key_q <= key;
            round_q <= 4'd0;
            age_q <= 5'd0;
            done_q <= 1'b0;
        end
    end
endmodule

