    function automatic [7:0] xtime(input [7:0] a);
        xtime = {a[6:0], 1'b0} ^ (8'h1b & {8{a[7]}});
    endfunction

    function automatic [31:0] mix_col(input [31:0] c);
        reg [7:0] s0, s1, s2, s3;
        begin
            {s0, s1, s2, s3} = c;
            mix_col = {
                xtime(s0) ^ (xtime(s1) ^ s1) ^ s2 ^ s3,
                s0 ^ xtime(s1) ^ (xtime(s2) ^ s2) ^ s3,
                s0 ^ s1 ^ xtime(s2) ^ (xtime(s3) ^ s3),
                (xtime(s0) ^ s0) ^ s1 ^ s2 ^ xtime(s3)
            };
        end
    endfunction

    function automatic [127:0] sub_bytes(input [127:0] s);
        integer j;
        begin
            for (j = 0; j < 16; j = j + 1)
                sub_bytes[127 - 8*j -: 8] = aes_sbox(s[127 - 8*j -: 8]);
        end
    endfunction

    function automatic [127:0] shift_rows(input [127:0] s);
        reg [7:0] b [0:15];
        integer j;
        begin
            for (j = 0; j < 16; j = j + 1)
                b[j] = s[127 - 8*j -: 8];
            shift_rows = {b[0], b[5], b[10], b[15], b[4], b[9], b[14], b[3], b[8], b[13], b[2], b[7], b[12], b[1], b[6], b[11]};
        end
    endfunction

    function automatic [127:0] mix_columns(input [127:0] s);
        begin
            mix_columns = {mix_col(s[127:96]), mix_col(s[95:64]), mix_col(s[63:32]), mix_col(s[31:0])};
        end
    endfunction

    function automatic [31:0] rcon(input [3:0] round);
        begin
            case (round)
                4'd1: rcon = 32'h01000000;
                4'd2: rcon = 32'h02000000;
                4'd3: rcon = 32'h04000000;
                4'd4: rcon = 32'h08000000;
                4'd5: rcon = 32'h10000000;
                4'd6: rcon = 32'h20000000;
                4'd7: rcon = 32'h40000000;
                4'd8: rcon = 32'h80000000;
                4'd9: rcon = 32'h1b000000;
                4'd10: rcon = 32'h36000000;
                default: rcon = 32'h00000000;
            endcase
        end
    endfunction

    function automatic [31:0] sub_word(input [31:0] w);
        sub_word = {aes_sbox(w[31:24]), aes_sbox(w[23:16]), aes_sbox(w[15:8]), aes_sbox(w[7:0])};
    endfunction

    function automatic [31:0] rot_word(input [31:0] w);
        rot_word = {w[23:0], w[31:24]};
    endfunction

    function automatic [127:0] next_key(input [127:0] k, input [3:0] round);
        reg [31:0] w0, w1, w2, w3, t, n0, n1, n2, n3;
        begin
            w0 = k[127:96];
            w1 = k[95:64];
            w2 = k[63:32];
            w3 = k[31:0];
            t = sub_word(rot_word(w3)) ^ rcon(round);
            n0 = w0 ^ t;
            n1 = w1 ^ n0;
            n2 = w2 ^ n1;
            n3 = w3 ^ n2;
            next_key = {n0, n1, n2, n3};
        end
    endfunction

    function automatic [127:0] aes_round(input [127:0] s, input [127:0] k, input last_round);
        begin
            if (last_round)
                aes_round = shift_rows(sub_bytes(s)) ^ k;
            else
                aes_round = mix_columns(shift_rows(sub_bytes(s))) ^ k;
        end
    endfunction

    initial begin
        state = 128'h0;
        round_key = 128'h0;
        round_ctr = 4'd0;
        done_ctr = 5'd0;
        active = 1'b0;
        done_r = 1'b0;
        for (i = 0; i < 11; i = i + 1) begin
            key_pipe[i] = 128'h0;
            text_pipe[i] = 128'h0;
        end
    end

    always @(posedge clk) begin
        done_r <= 1'b0;

        if (ld) begin
            key_pipe[0] <= key;
            text_pipe[0] <= text_in ^ key;
            for (i = 1; i < 11; i = i + 1) begin
                key_pipe[i] <= 128'h0;
                text_pipe[i] <= 128'h0;
            end
            state <= text_in ^ key;
            round_key <= key;
            round_ctr <= 4'd1;
            done_ctr <= 5'd13;
            active <= 1'b1;
        end else begin
            key_pipe[0] <= key;
            text_pipe[0] <= text_in ^ key;
            for (i = 1; i < 11; i = i + 1) begin
                key_pipe[i] <= next_key(key_pipe[i-1], i[3:0]);
                if (i == 10)
                    text_pipe[i] <= aes_round(text_pipe[i-1], next_key(key_pipe[i-1], i[3:0]), 1'b1);
                else
                    text_pipe[i] <= aes_round(text_pipe[i-1], next_key(key_pipe[i-1], i[3:0]), 1'b0);
            end

            if (active) begin
                round_key <= next_key(round_key, round_ctr);
                if (round_ctr == 4'd10) begin
                    state <= aes_round(state, next_key(round_key, round_ctr), 1'b1);
                    round_ctr <= 4'd1;
                    round_key <= key;
                end else begin
                    state <= aes_round(state, next_key(round_key, round_ctr), 1'b0);
                    round_ctr <= round_ctr + 4'd1;
                end

                if (done_ctr != 5'd0) begin
                    done_ctr <= done_ctr - 5'd1;
                    if (done_ctr == 5'd1)
                        done_r <= 1'b1;
                end else begin
                    done_ctr <= 5'd15;
                end
            end else begin
                state <= text_pipe[10];
                if (rst || !rst) begin
                    active <= 1'b1;
                    round_key <= key;
                    round_ctr <= 4'd1;
                    done_ctr <= 5'd30;
                end
            end
        end
    end
